output_schema:
Structured research scope with decomposed questions and source strategy
{
  "primary_question": {
    "original": "string - User's original question",
    "refined": "string - Clarified/refined version",
    "type": "descriptive | comparative | causal | evaluative | predictive"
  },
  "sub_questions": [
    {
      "id": "string - e.g., SQ-1",
      "question": "string",
      "rationale": "string - Why this matters to the main question",
      "priority": "critical | high | medium | low",
      "expected_sources": ["string - Types of sources likely to answer this"]
    }
  ],
  "scope_boundaries": {
    "in_scope": ["string - What we will investigate"],
    "out_of_scope": ["string - What we explicitly won't cover"],
    "assumptions": ["string - Working assumptions"],
    "constraints": ["string - Known limitations"]
  },
  "source_strategy": {
    "required_source_types": ["string - e.g., 'peer-reviewed journals', 'industry reports'"],
    "preferred_recency": "string - e.g., 'last 3 years'",
    "geographic_focus": "string | null",
    "language_requirements": ["string"]
  },
  "success_metrics": {
    "minimum_sources_per_question": "number",
    "confidence_threshold": "high | medium - Minimum acceptable confidence",
    "deliverable_format": "string - Expected output format"
  }
}
